pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // Bound burnAmount to be within totalSupply initially (zero) and avoid overflow.
        // The reference contract starts with totalSupply = 0 because initialSupply = 0.
        // To have a meaningful burn, we first mint tokens to owner and then burn.
        uint256 mintAmount = 1000 ether;
        vm.prank(address(this));
        c.mintToken(address(this), mintAmount);
        uint256 supplyBefore = c.totalSupply();
        require(burnAmount <= supplyBefore, "fuzz bound violated");
        // Perform the burn
        vm.prank(address(this));
        c.burn(burnAmount);
        uint256 supplyAfter = c.totalSupply();
        // The invariant: totalSupply after burn should equal supplyBefore - burnAmount exactly.
        assertTrue(supplyAfter == supplyBefore - burnAmount);
    }
}

