        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        vm.assume(burnAmount > 0);
        uint256 supplyBefore = c.totalSupply();
        // mint tokens to caller so that they have enough balance to burn
        address owner = c.owner();
        vm.prank(owner);
        c.mintToken(caller, burnAmount);
        // caller (non-owner) attempts to burn
        vm.prank(caller);
        // capture success of burn call
        bool ok;
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }
        uint256 supplyAfter = c.totalSupply();
        // If burn succeeded (ok == true), totalSupply must have decreased only when caller is owner.
        // Owner mints and burns are not tested here; we only test a non-owner caller.
        assertTrue(!ok || supplyAfter == supplyBefore);
    }
}

