pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address burner) public {
        // 1. Admissible domain: burner not owner, burner has sufficient balance via minting
        vm.assume(burner != address(0));
        vm.deal(burner, 0);

        // Mint tokens to the burner so they have something to burn
        vm.prank(c.owner());
        c.mintToken(burner, burnAmount);
        vm.assume(burnAmount > 0);

        // Record state before burn
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(burner);

        // 2. Attempt burn as the non-owner burner
        vm.prank(burner);
        bool ok;
        try c.burn(burnAmount) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. General rule: if burn succeeded, totalSupply must reflect the burn
        uint256 supplyAfter = c.totalSupply();
        bool ruleHolds = ok ? supplyAfter == supplyBefore - burnAmount : supplyAfter == supplyBefore;
        assertTrue(ruleHolds);
    }
}

