pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount, address frozenTarget, bool freeze) public {
        // Assume reasonable values
        initialSupply = bound(initialSupply, 0, type(uint256).max / 2);
        burnAmount = bound(burnAmount, 0, initialSupply);
        // Need a non-zero supply and burn to test the property meaningfully
        vm.assume(initialSupply > 0);
        vm.assume(burnAmount > 0);

        // Deploy with a valid name/symbol and supply
        c = new C(initialSupply, "Token", "TKN");

        // The current owner is this contract because setUp() used the default caller
        // Freeze an account if the fuzzer says so (must be the owner calling freeze)
        // We freeze the address of the owner itself, as the property is about owner's balance after minting to frozen accounts
        // But first, the owner must have the supply. The constructor gave balance to msg.sender, which is this contract (the test).
        // We will call freeze on the owner itself to make the account frozen, and then burn. But the burn requires the caller (owner) not be frozen.
        // So we freeze a different account, or freeze the owner after burn? The test must pass for the reference.

        // Strategy: The owner freezes some arbitrary address (or itself after transferring?), then burns.
        // The reference property: For the reference contract, after any operation, the total supply should be consistent with the owner's balance,
        // assuming no tokens are minted to or transferred from the owner, and no other addresses have tokens besides the frozen ones.
        // Since mintToken and transfer can alter balances arbitrarily for the fuzzer, the property must hold for the specific scenario we construct.

        // Let's use: The owner freezes a target, then burns some amount. Before the burn, only the owner has tokens (from constructor).
        // So totalSupply == balanceOf(owner) always holds initially.
        // After a burn by the owner, totalSupply should be decreased by burnAmount, and balanceOf(owner) should also decrease by burnAmount.
        // The bug fails to decrease totalSupply. So we compare totalSupply and the owner's balance after the burn.
        // Since no other accounts have balance, totalSupply == balanceOf(owner) should still hold for the reference after burn.
        // The bug violates this.

        // However, the owner can be frozen? If the owner is frozen, they cannot call burn (require(!frozenAccount[_from]) in _transfer? No, burn does not use _transfer, it directly checks balanceOf[msg.sender] >= _value).
        // burn does not check frozenAccount, so the owner can burn even if frozen. But the rule: "after a burn, totalSupply == balanceOf(owner)" holds only if no other accounts have tokens.
        // Since the owner can freeze an account and mint to it? No, mint is also onlyOwner, but if we don't call mint, it's fine.

        // So set up: freeze some target (not the owner, to avoid interfering with burn? Actually, freezing does not remove tokens, just prevents transfers).
        // The frozen target initially has 0 balance, so totalSupply == balanceOf(owner) still holds before burn.

        // freeze the target (if freeze is true)
        vm.prank(address(this)); // owner is this contract, because setUp() was called by this contract and constructor sets owner = msg.sender
        c.freezeAccount(frozenTarget, freeze);

        // Record totalSupply and owner balance before burn
        uint256 totalBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(address(this));

        // Burn
        vm.prank(address(this));
        c.burn(burnAmount);

        uint256 totalAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(address(this));

        // The invariant: Since no other address has balance (the frozen target has 0 balance, and no mint/transfer occurred),
        // totalSupply should equal owner's balance after the burn.
        // The reference passes; the bug has totalSupply unchanged, so totalAfter == totalBefore != ownerBalAfter.
        assertTrue(totalAfter == ownerBalAfter);
    }
}

